create function public.limit_community_posts() returns trigger language plpgsql security invoker set search_path='' as $$ begin if (select count(*) from public.community_posts where user_id=new.user_id and created_at>now()-interval '1 minute')>=5 then raise exception 'Lütfen yeni paylaşım için biraz bekle.' using errcode='P0001'; end if; return new; end $$; create trigger limit_community_posts before insert on public.community_posts for each row execute function public.limit_community_posts(); revoke all on function public.limit_community_posts() from public,anon; grant execute on function public.limit_community_posts() to authenticated;
